 }
+
+func TestActiveRequiresExecutableRuntime(t *testing.T) {
+	home := t.TempDir()
+	version := "2.1.319"
+	runtime := refFor(home, version).path
+	if err := os.MkdirAll(filepath.Dir(runtime), 0o700); err != nil {
+		t.Fatal(err)
+	}
+	if err := os.WriteFile(filepath.Join(Root(home), ActiveFile), []byte(version+"\n"), 0o600); err != nil {
+		t.Fatal(err)
+	}
+	if err := os.WriteFile(runtime, []byte("runtime fixture\n"), 0o644); err != nil {
+		t.Fatal(err)
+	}
+	for _, c := range []struct {
+		name          string
+		mode          os.FileMode
+		version, path string
+	}{
+		{"not executable", 0o644, Version, RuntimePath(home)},
+		{"executable", 0o755, version, runtime},
+	} {
+		t.Run(c.name, func(t *testing.T) {
+			if err := os.Chmod(runtime, c.mode); err != nil {
+				t.Fatal(err)
+			}
+			if v, p := Active(home); v != c.version || p != c.path {
+				t.Errorf("Active = %q %q, want %q %q", v, p, c.version, c.path)
+			}
+		})
+	}
+}

